/*
 * Copyright (c) 2023, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

import React from 'react';
import loadable from '@loadable/component';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

// Components
import { Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
import { configureRoutes } from '@salesforce/retail-react-app/app/utils/routes-utils';
import { routes as _routes } from '@salesforce/retail-react-app/app/routes';

const fallback = <Skeleton height="75vh" width="100%" />;

// Create your pages here and add them to the routes array
// Use loadable to split code into smaller js chunks
const Home = loadable(() => import('./pages/home'), { fallback });
const MyNewRoute = loadable(() => import('./pages/my-new-route'));
const Experience = loadable(() => import('./pages/experience'), { fallback });

const routes = [
  {
    path: '/',
    component: Home,
    exact: true,
  },
  {
    path: '/my-new-route',
    component: MyNewRoute,
  },
  ..._routes,
  // Contentful Studio/Experience pages — fallback after all SFCC routes.
  // `configureRoutes` strips PWA Kit's '*' catch-all so this is safely reached only for paths no other route matched.
  {
    path: '/:slug',
    component: Experience,
  },
];

export default () => {
  const config = getConfig();
  return configureRoutes(routes, config, {
    ignoredRoutes: ['/callback', '*'],
  });
};

/**
 * Zimmermann country configuration — single source of truth for all
 * locale, currency, shipping, checkout, and boutique-region mappings.
 *
 * SFCC site IDs and BM locale IDs verified against bkzk-002 Business Manager (2026-06-13).
 *
 * Used by: URL routing, IP-detection prompt, checkout redirect logic,
 * boutique location filtering, hreflang generation.
 *
 * When adding a country:
 *   1. Add an entry here.
 *   2. Add the locale + currency to config/sites.js.
 *   3. Ensure a compiled translation exists in overrides/app/static/translations/compiled/.
 *
 * Unresolved — do not hard-code:
 *   - NZ/Oceania currency routing
 *   - Denmark routing
 *   - China
 */

/** The 7 independent SFCC site IDs. Each is a hard routing + config boundary. */
export type SfccSiteId =
  | 'ZimmermannAU'
  | 'ZimmermannUS'
  | 'ZimmermannUK'
  | 'ZimmermannEU'
  | 'ZimmermannEUIntl'
  | 'ZimmermannHK'
  | 'ZimmermannME';

/**
 * Who owns checkout for this site's domestic path.
 * For HK and ME, Global-e always owns checkout AND pricing from PDP onward.
 * For AU, US, GB, EU: SFCC owns domestic paths; Global-e takes over when the
 * user's shipping destination is outside the site's domestic market.
 */
export type CheckoutOwner = 'sfcc' | 'global-e' | 'hybrid';

export type CountryConfig = {
  /** URL path segment, e.g. 'au', 'us', 'fr-eu' */
  urlSlug: string;
  /** Which of the 6 SFCC sites this locale routes to */
  sfccSiteId: SfccSiteId;
  /** IETF locale used by PWA Kit / SFCC, e.g. 'en-AU' */
  locale: string;
  /** ISO 4217 currency code */
  currency: string;
  /** ISO 3166-1 alpha-2 shipping/tax country */
  shippingCountry: string;
  /**
   * Checkout owner for this site's domestic path.
   * Branch checkout AND pricing logic from this field at PDP/cart level —
   * not only at the checkout page.
   */
  checkoutOwner: CheckoutOwner;
  /**
   * When true, Global-e owns pricing, currency, and tax display from PDP
   * onward — do not render SFCC prices on these paths.
   */
  globalEPricing: boolean;
  /** Key used to filter boutique locations for this region */
  boutiqueRegion: string;
};

/**
 * Keyed by urlSlug for O(1) lookup in routing/middleware.
 * AU is the exception: it has no URL prefix (root domain). Its key is 'au'
 * but urlSlug is '' — routing falls back to DEFAULT_COUNTRY_SLUG when no
 * prefix is detected.
 */
export const COUNTRIES: Record<string, CountryConfig> = {
  // ── Domestic SFCC sites ──────────────────────────────────────────────────
  au: {
    urlSlug: '', // AU uses the root domain — no prefix (x-default hreflang)
    sfccSiteId: 'ZimmermannAU',
    locale: 'en',
    currency: 'AUD',
    shippingCountry: 'AU',
    checkoutOwner: 'sfcc',
    globalEPricing: false,
    boutiqueRegion: 'australia',
  },
  us: {
    urlSlug: 'us',
    sfccSiteId: 'ZimmermannUS',
    locale: 'en-US',
    currency: 'USD',
    shippingCountry: 'US',
    checkoutOwner: 'hybrid',
    globalEPricing: false,
    boutiqueRegion: 'usa',
  },
  // ZimmermannUS international path — same SFCC site as /us/, Global-e owns checkout + pricing
  'en-ca': {
    urlSlug: 'en-ca',
    sfccSiteId: 'ZimmermannUS',
    locale: 'en-US',
    currency: 'USD',
    shippingCountry: 'CA',
    checkoutOwner: 'global-e',
    globalEPricing: true,
    boutiqueRegion: 'usa', // TBC
  },
  uk: {
    urlSlug: 'uk',
    sfccSiteId: 'ZimmermannUK',
    locale: 'en-GB',
    currency: 'GBP',
    shippingCountry: 'GB',
    checkoutOwner: 'sfcc',
    globalEPricing: false,
    boutiqueRegion: 'uk',
  },
  // ── EU domestic site — 4 languages (EN/FR/IT/ES), one SFCC site ─────────
  'en-eu': {
    urlSlug: 'en-eu',
    sfccSiteId: 'ZimmermannEU',
    locale: 'en-GB',
    currency: 'EUR',
    shippingCountry: 'DE', // placeholder; shipping country resolved at checkout
    checkoutOwner: 'sfcc',
    globalEPricing: false,
    boutiqueRegion: 'europe',
  },
  'fr-eu': {
    urlSlug: 'fr-eu',
    sfccSiteId: 'ZimmermannEU',
    locale: 'fr',
    currency: 'EUR',
    shippingCountry: 'FR',
    checkoutOwner: 'sfcc',
    globalEPricing: false,
    boutiqueRegion: 'europe',
  },
  'it-eu': {
    urlSlug: 'it-eu',
    sfccSiteId: 'ZimmermannEU',
    locale: 'it',
    currency: 'EUR',
    shippingCountry: 'IT', // placeholder; shipping country resolved at checkout
    checkoutOwner: 'sfcc',
    globalEPricing: false,
    boutiqueRegion: 'europe',
  },
  'es-eu': {
    urlSlug: 'es-eu',
    sfccSiteId: 'ZimmermannEU',
    locale: 'es',
    currency: 'EUR',
    shippingCountry: 'ES', // placeholder; shipping country resolved at checkout
    checkoutOwner: 'sfcc',
    globalEPricing: false,
    boutiqueRegion: 'europe',
  },
  // ── EU international — Global-e checkout (non-EU Europe + Africa + ROW) ──
  'en-ch': {
    urlSlug: 'en-ch',
    sfccSiteId: 'ZimmermannEUIntl',
    locale: 'en-CH',
    currency: 'EUR',
    shippingCountry: 'CH', // placeholder; Global-e resolves shipping country
    checkoutOwner: 'global-e',
    globalEPricing: true,
    boutiqueRegion: 'europe',
  },
  // ── Global-e sites — pricing + checkout always owned by Global-e ─────────
  hk: {
    urlSlug: 'hk',
    sfccSiteId: 'ZimmermannHK',
    locale: 'en-HK',
    currency: 'HKD',
    shippingCountry: 'HK',
    checkoutOwner: 'global-e',
    globalEPricing: true,
    boutiqueRegion: 'hong-kong',
  },
  'en-ae': {
    urlSlug: 'en-ae',
    sfccSiteId: 'ZimmermannME',
    locale: 'en-AE',
    currency: 'AED',
    shippingCountry: 'AE',
    checkoutOwner: 'global-e',
    globalEPricing: true,
    boutiqueRegion: 'middle-east',
  },
};

/** Fallback when no URL slug is present or IP detection fails. */
export const DEFAULT_COUNTRY_SLUG = 'au';

/** Lookup by ISO 3166-1 alpha-2 code — used by IP-detection prompt. */
export const COUNTRY_BY_SHIPPING_CODE: Record<string, CountryConfig> = Object.fromEntries(
  Object.values(COUNTRIES).map((c) => [c.shippingCountry, c]),
);

