216	          {/* Desktop left: nav categories (children) + search icon — no flex grow so space-between pushes Account/Saved/Bag to the right */}
217	          <Flex display={{ base: 'none', lg: 'flex' }} alignItems="center">
218	            <Box {...styles.bodyContainer}>{children}</Box>
219	            {/* TEMP: debug search input — remove once search overlay is implemented */}
220	            <Box ml={4} minW="240px">
221	              <Search
222	                placeholder={intl.formatMessage({
223	                  id: 'header.field.placeholder.search_for_products',
