278	                </PopoverTrigger>
279	
280	                <PopoverContent
281	                  {...styles.popoverContent}
282	                  onMouseLeave={() => {
283	                    hasEnterPopoverContent.current = false;
284	                    onAccountMenuClose();
285	                  }}
286	                  onMouseOver={() => {
287	                    hasEnterPopoverContent.current = true;
288	                  }}
289	                  {...getAccountMenuDisclosureProps()}
290	                >
291	                  <PopoverArrow />
292	                  <PopoverHeader>
293	                    <Text as="h2" fontSize="l" fontFamily="body" fontWeight="700">
294	                      {intl.formatMessage({
295	                        defaultMessage: 'My Account',
296	                        id: 'header.popover.title.my_account',
297	                      })}
298	                    </Text>
299	                  </PopoverHeader>
300	                  <PopoverBody>
301	                    <Box as="nav">
302	                      <Stack spacing={0} as="ul" data-testid="account-detail-nav">
303	                        {filteredNavLinks.map((link) => {
304	                          const LinkIcon = link.icon;
305	                          return (
306	                            <Box key={link.name} position="relative" as="li" listStyleType="none">
307	                              <Button
308	                                as={Link}
309	                                to={`/account${link.path}`}
310	                                useNavLink={true}
311	                                variant="menu-link"
312	                                leftIcon={<LinkIcon boxSize={5} />}
313	                                width="100%"
314	                              >
315	                                {intl.formatMessage(messages[link.name])}
316	                              </Button>
317	                            </Box>
318	                          );
319	                        })}
320	                      </Stack>
321	                    </Box>
322	                  </PopoverBody>
323	                  <PopoverFooter onClick={onSignoutClick} cursor="pointer">
324	                    <Divider colorScheme="gray" />
325	                    <Button variant="unstyled" {...styles.signout}>
326	                      <Flex>
327	                        <SignoutIcon aria-hidden={true} boxSize={5} {...styles.signoutIcon} />
328	                        <Text as="span" {...styles.signoutText}>
329	                          {intl.formatMessage({
330	                            defaultMessage: 'Log out',
331	                            id: 'header.popover.action.log_out',
332	                          })}
333	                        </Text>
334	                      </Flex>
335	                    </Button>
336	                  </PopoverFooter>
337	                </PopoverContent>
338	              </Popover>
339	            )}
340	            <ButtonWithRegistration variant="unstyled" {...styles.desktopActionButton} onClick={onWishlistClick}>
341	              Saved
342	            </ButtonWithRegistration>
343	            <Button variant="unstyled" {...styles.desktopActionButton} onClick={onMyCartClick}>
344	              Bag{basket && totalItems > 0 ? ` (${String(totalItems)})` : ''}
345	            </Button>
346	          </Flex>
347	
348	          {/* Mobile right: icon cluster */}
349	          <Flex display={{ base: 'flex', lg: 'none' }} alignItems="center" gap={2}>
350	            <IconButton
351	              aria-label={intl.formatMessage({
352	                id: 'header.button.assistive_msg.search',
353	                defaultMessage: 'Search',
354	              })}
355	              icon={<SearchIcon />}
356	              variant="unstyled"
357	              {...styles.icons}
358	            />
359	            {/* <IconButtonWithRegistration
360	              icon={<AccountIcon />}
361	              aria-label={intl.formatMessage({
362	                id: 'header.button.assistive_msg.my_account',
363	                defaultMessage: 'My Account',
364	              })}
365	              variant="unstyled"
366	              {...styles.icons}
367	              {...styles.accountIcon}
368	              onClick={onMyAccountClick}
369	            />
370	            <IconButtonWithRegistration
371	              aria-label={intl.formatMessage({
372	                defaultMessage: 'Wishlist',
373	                id: 'header.button.assistive_msg.wishlist',
374	              })}
375	              icon={<HeartIcon />}
376	              variant="unstyled"
377	              {...styles.icons}
378	              {...styles.wishlistIcon}
379	              onClick={onWishlistClick}
380	            /> */}
381	            {storeLocatorEnabled && (
382	              <IconButton
383	                aria-label={intl.formatMessage({
384	                  defaultMessage: 'Store Locator',
385	                  id: 'header.button.assistive_msg.store_locator',
386	                })}
387	                icon={<StoreIcon />}
388	                {...styles.icons}
389	                variant="unstyled"
390	                onClick={onStoreLocatorClick}
391	              />
392	            )}
393	            <IconButton
394	              aria-label={intl.formatMessage(
395	                {
396	                  id: 'header.button.assistive_msg.my_cart_with_num_items',
397	                  defaultMessage: 'My cart, number of items: {numItems}',
398	                },
399	                { numItems: totalItems },
400	              )}
401	              icon={
402	                <>
403	                  <BasketIcon />
404	                  {basket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
405	                </>
406	              }
407	              variant="unstyled"
408	              {...styles.icons}
409	              onClick={onMyCartClick}
410	            />
411	          </Flex>
412	        </Flex>
413	
414	        {/* ── Row 2: logo only ────────────────────────────────────────────── */}
415	        <Flex {...styles.logoBar}>
416	          <Button
417	            aria-label={intl.formatMessage({
418	              id: 'header.button.assistive_msg.logo',
419	              defaultMessage: 'Logo',
420	            })}
421	            variant="unstyled"
422	            onClick={onLogoClick}
423	            {...styles.logoButton}
424	          >
425	            <BrandLogo {...styles.logo} />
426	          </Button>
427	        </Flex>
428	
429	        {/* Mobile-only search — commented out, pending searchPopover implementation */}
430	        {/* <HideOnDesktop display={{ base: 'block', lg: 'none' }}><SearchBar /></HideOnDesktop> */}
431	      </Box>
432	    </Box>
433	  );
434	};
435	
436	export default Header;
