import React from 'react';
import { Box, Image } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ContentfulLivePreview } from '@contentful/live-preview';
import type { ContentfulAsset } from '../../types/contentful';

type HeroBannerProps = {
  heroBanner: ContentfulAsset;
  entryId?: string;
  locale?: string;
};

export const HeroBanner = ({ heroBanner, entryId, locale = 'en-US' }: HeroBannerProps) => {
  if (!heroBanner?.fields?.file?.url) {
    console.error('HeroBanner: Missing required data', heroBanner);
    return null;
  }

  const { fields } = heroBanner;
  const imageUrl = `https:${fields.file.url}`;
  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'heroBanner', locale }) : {};

  return (
    <Box position="relative" width="full" height={{ base: '240px', md: '400px' }} {...inspectorProps}>
      <Image
        src={imageUrl}
        alt={fields.title || 'Hero banner'}
        objectFit="cover"
        width="full"
        height="full"
        fallbackSrc="https://via.placeholder.com/1920x600?text=Loading..."
      />
    </Box>
  );
};

import { defineComponents } from '@contentful/experiences-sdk-react';
import CollectionHero from './collectionHero';
import ImageText from './imageText';
import ShoppableImage from './shoppableImage';

defineComponents([
  {
    component: CollectionHero,
    definition: {
      id: 'collection-hero',
      name: 'Collection Hero',
      variables: {
        headline: { type: 'Text', displayName: 'Headline', defaultValue: '' },
        subheadline: { type: 'Text', displayName: 'Subheadline', defaultValue: '' },
        ctaLabel: { type: 'Text', displayName: 'CTA Label', defaultValue: '' },
        ctaUrl: { type: 'Text', displayName: 'CTA URL', defaultValue: '' },
        backgroundImage: { type: 'Media', displayName: 'Background Image', defaultValue: '' },
      },
    },
  },
  {
    component: ImageText,
    definition: {
      id: 'image-text',
      name: 'Image + Text',
      variables: {
        image: { type: 'Media', displayName: 'Image', defaultValue: '' },
        imageAlt: { type: 'Text', displayName: 'Image Alt Text', defaultValue: '' },
        headline: { type: 'Text', displayName: 'Headline', defaultValue: '' },
        body: { type: 'Text', displayName: 'Body', defaultValue: '' },
