        hotspots: {
          type: 'Text',
          displayName: 'Hotspots (JSON)',
          defaultValue: '[{"x":50,"y":50,"productId":""}]',
          description: 'Array of hotspots. Each: { "x": 0–100, "y": 0–100, "productId": "SFCC product ID" }',
        },
      },
    },
  },
]);

// helmet uses `export = helmet` (CommonJS), so ContentSecurityPolicyOptions must be
// imported from its submodule directly rather than from the package root.
import type { ContentSecurityPolicyOptions } from 'helmet/dist/middlewares/content-security-policy';

export const contentSecurityPolicy: ContentSecurityPolicyOptions = {
  useDefaults: true,
  directives: {
    'img-src': [
      // Default source for product images - replace with your CDN
      '*.commercecloud.salesforce.com',
      '*.demandware.net',
      '*.adyen.com', // Payment gateways
      'pay.google.com', // Google Pay payment handler icon
      'www.gstatic.com', // optional, if icon is on gstatic
      // Contentful images
      'images.ctfassets.net',
    ],
    'script-src': [
      // Used by the service worker in /worker/main.js
      'storage.googleapis.com',
      // Connect to Google Cloud APIs
      'maps.googleapis.com',
      'places.googleapis.com',
      // Payment gateways
      '*.stripe.com',
      '*.paypal.com',
      '*.adyen.com',
      'pay.google.com',
      'www.gstatic.com',
      '*.demandware.net', // Used to load a valid payment scripts in test environment
    ],
    'connect-src': [
      // Connect to Contentful API
      'cdn.contentful.com',
      'preview.contentful.com',
      // Connect to Einstein APIs
      'api.cquotient.com',
      // Connect to DataCloud APIs
      '*.c360a.salesforce.com',
      // Connect to Google Cloud APIs
      'maps.googleapis.com',
      'places.googleapis.com',
      // Connect to SCRT2 URLs
      '*.salesforce-scrt.com',
      // Payment gateways
      // Note: Google Pay requires different CSP entries depending on the integration and environment.
      // - 'pay.google.com' and 'payments.google.com' are generally needed for the SDK to load and create payment tokens.
      // - 'google.com/pay/' and 'www.google.com/pay/' may be required for certain flows (especially with Adyen) or in some browsers
      //   where the interactive payment sheet makes server calls directly to google.com/pay.
      // - You may need to adjust these URLs based on your environments.
      '*.demandware.net', // Used to load a valid payment scripts in test environment
      '*.adyen.com',
      '*.paypal.com',
      'pay.google.com',
      'payments.google.com',
      'google.com/pay',
      'google.com/pay/',
      'www.google.com/pay',
      'www.google.com/pay/',
    ],
    'frame-src': [
      // Allow frames from Salesforce site.com (Needed for MIAW)
      '*.site.com',
      // Payment gateways
      '*.stripe.com',
      '*.paypal.com',
      '*.adyen.com',
      'payments.google.com',
      'pay.google.com',
    ],
    // Allow Contentful to embed /preview in its Live Preview iframe
    'frame-ancestors': ["'self'", 'https://app.contentful.com'],
  },
};

/**
 * Undici connection pools for SSR upstream origins (TSD §12.1 blast-radius mitigation).
 *
 * Each pool caps the concurrent connections to one origin so a slow or flooded integration
 * cannot exhaust connections for unrelated services. Use the per-call `dispatcher` option
 * on `fetch()` calls inside ssr.js to route requests through the correct pool:
 *
 *   import {fetch} from 'undici'
 *   import {sfccPaymentsPool} from './ssr/connectionPools'
 *   const data = await fetch(url, {dispatcher: sfccPaymentsPool})
 *
 * Connection caps and timeouts are set to the TSD §12.1 planned values.
 * Validate them on Stage (§9.3) — undici emits queue-depth and connection-wait
 * metrics via diagnostic channel events for tuning.
 *
 * IMPORTANT: Booxi base URL must be confirmed with the Integration team before enabling
 * that pool. See the TODO below.
 */
import { Pool } from 'undici';

/** SLAS JWKS token validation (passwordless login, reset password). Calls are rare — jose caches the JWK set. */
export const sfccScapiPool = new Pool(
  `https://${process.env.COMMERCE_API_SHORT_CODE ?? 'COMMERCE_API_SHORT_CODE'}.api.commercecloud.salesforce.com`,
  { connections: 5, connectTimeout: 5_000, bodyTimeout: 8_000 },
);

/**
 * Payment method metadata on every checkout page SSR.
 * Separate from sfccScapiPool so a checkout traffic spike cannot consume SLAS connections.
 * TODO: Confirm the exact hostname of config.app.sfPayments.metadataUrl with the Integration team
 * and replace the placeholder origin here.
 */
export const sfccPaymentsPool = new Pool(
  `https://${process.env.SFCC_PAYMENTS_HOST ?? 'SFCC_PAYMENTS_HOST.demandware.net'}`,
  { connections: 10, connectTimeout: 5_000, bodyTimeout: 8_000 },
);

/**
 * Order history, order details, boutique/BOPIS stock check, GiveX balance check.
 * Highest cap — broadest call surface across My Account and PDP.
 */
export const mulesoftPool = new Pool(process.env.MULESOFT_BASE_URL ?? 'https://MULESOFT_BASE_URL', {
  connections: 20,
  connectTimeout: 5_000,
  bodyTimeout: 10_000,
});

/** Marketing Cloud client-credentials token exchange. Token cached at module scope for 15 min. */
export const marketingCloudAuthPool = new Pool(
  `https://${process.env.MARKETING_CLOUD_SUBDOMAIN ?? 'MARKETING_CLOUD_SUBDOMAIN'}.auth.marketingcloudapis.com`,
  { connections: 5, connectTimeout: 5_000, bodyTimeout: 15_000 },
);

/** Magic-link email send (passwordless login, reset password). Higher body timeout — email APIs can respond slowly. */
export const marketingCloudRestPool = new Pool(
  `https://${process.env.MARKETING_CLOUD_SUBDOMAIN ?? 'MARKETING_CLOUD_SUBDOMAIN'}.rest.marketingcloudapis.com`,
  { connections: 5, connectTimeout: 5_000, bodyTimeout: 15_000 },
);

/** Address autocomplete at checkout (CFD-023, CFD-030, CFD-059). Short timeouts — graceful fallback to manual entry. */
export const googlePlacesPool = new Pool('https://places.googleapis.com', {
  connections: 5,
  connectTimeout: 3_000,
  bodyTimeout: 5_000,
});

/**
 * Boutique appointment history in My Account (CRM-165–167).
 * TODO: Replace placeholder origin with confirmed Booxi base URL from the Integration team.
 */
export const booxiPool = new Pool(process.env.BOOXI_BASE_URL ?? 'https://BOOXI_BASE_URL', {
  connections: 5,
  connectTimeout: 3_000,
  bodyTimeout: 5_000,
});

