import React, { useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { Box, Spinner, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import { createClient } from 'contentful';
import { ExperienceRoot, useFetchBySlug } from '@contentful/experiences-sdk-react';
import { getContentfulConfig } from '../../config/contentful';

// Side-effect import — registers experience components with the Contentful Experiences SDK (cached, so this is fine)
import '../../components/contentful/experiences/definitions';

const EXPERIENCE_TYPE_ID = 'collectionPageExp';
const LOCALE = 'en-US';

type ExperiencePageProps = {
  slug: string;
};

const ExperiencePage = ({ slug }: ExperiencePageProps) => {
  const { spaceId, environment, previewAccessToken, accessToken } = getContentfulConfig() ?? {};
  const resolvedToken = previewAccessToken || accessToken;

  const client = useMemo(
    () => {
      if (!spaceId || !resolvedToken) return null;
      return createClient({
        space: spaceId,
        environment,
        // preview token → shows draft content (local/staging); delivery token → CDN-cached published content (production)
        accessToken: resolvedToken,
        host: previewAccessToken ? 'preview.contentful.com' : 'cdn.contentful.com',
      });
    },
    [spaceId, environment, previewAccessToken, resolvedToken],
  );

  if (!client) {
    return (
      <Box p={8}>
        <Text color="red.500">Page not found.</Text>
      </Box>
    );
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { experience, isLoading, error } = useFetchBySlug({
    client: client as any,
    slug,
    experienceTypeId: EXPERIENCE_TYPE_ID,
    localeCode: LOCALE,
  });

  if (isLoading) {
    return (
      <Box p={8} display="flex" justifyContent="center">
        <Spinner size="xl" />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={8}>
        <Text color="red.500">Page not found.</Text>
      </Box>
    );
  }

  return <ExperienceRoot experience={experience} locale={LOCALE} />;
};

const Experience = () => {
  const { pathname } = useLocation();
  const slug = pathname.slice(1); // strip leading '/'

  return <ExperiencePage slug={slug} />;
};

Experience.getTemplateName = () => 'experience';

export default Experience;

