import React from 'react';
import { Button as ChakraButton, chakra, type ButtonProps as ChakraButtonProps } from '@chakra-ui/react';

export type ButtonProps = Omit<ChakraButtonProps, 'variant' | 'size'> & {
  variant?: 'primary' | 'secondary';
  size?: 'lg' | 'sm';
  /**
   * Optional price label displayed on the right-hand side of a large button
   * (e.g. "Add to Bag" + "$575"). Only renders when `size` is `'lg'`.
   */
  price?: string;
};

/**
 * Zimmermann branded button. Two variants (primary/secondary) and two sizes
 * (lg/sm) — all states (hover, pressed, disabled, focused) are handled via the
 * Chakra theme in `overrides/app/theme/components/button.ts`.
 *
 * Pass `price` to show a split-label large button (e.g. "ADD TO BAG $575").
 * The button defaults to `w="full"` in that case so justify-between has room
 * to spread; override via the `w` prop if a fixed width is needed.
 */
export const Button = ({ children, variant = 'primary', size = 'lg', price, ...rest }: ButtonProps) => {
  if (price && size === 'lg') {
    return (
      <ChakraButton variant={variant} size={size} w="full" justifyContent="space-between" gap={4} {...rest}>
        <chakra.span>{children}</chakra.span>
        <chakra.span>{price}</chakra.span>
      </ChakraButton>
    );
  }

  return (
    <ChakraButton variant={variant} size={size} {...rest}>
      {children}
    </ChakraButton>
  );
};

