import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

type ProxyConfig = { host: string; path: string };
type FullConfig = { app: Record<string, unknown>; ssrParameters?: { proxyConfigs?: ProxyConfig[] } };

/**
 * Rewrites an absolute SFCC static asset URL to go through the PWA Kit proxy,
 * avoiding direct browser access to the Demandware host which is typically
 * blocked by Cloudflare WAF outside of the Commerce Cloud network.
 */
export const proxyImageUrl = (url: string): string => {
  try {
    const { hostname, pathname, search } = new URL(url);
    const { ssrParameters } = getConfig() as FullConfig;
    const match = ssrParameters?.proxyConfigs?.find((c) => c.host === hostname);
    if (match) return `/mobify/proxy/${match.path}${pathname}${search}`;
  } catch (_) {
    // relative or malformed URL — return as-is
  }
  return url;
};

// Source: Figma "Design Workspace", node 2081:52454. Semantic colour tokens.
export const colors = {
  background: {
    '01': '#F9F8F6',
    '02': '#F6F4F1',
    '03': '#FBF5EF',
    '04': '#F2E9E0',
    '05': '#191919',
    '06': '#282828',
    '07': '#FFFFFF',
  },
  text: {
    default: '#191919',
    secondary: '#666666',
    inverse: '#FFFFFF',
    inverseGrey: '#939393',
    muted: '#969696',
    status: {
      success: '#6E7D63',
      error: '#9C0000',
      errorBackground: '#FFE4E4',
    },
  },
  border: {
    default: '#E6E6E6',
    secondary: '#D1D1D1',
    focus: '#191919',
    error: '#9C0000',
  },
  icon: {
    default: '#191919',
  },
};

// NOTE: Font family names below match the Figma file (FONTSPRING DEMO licence).
// Update to the licensed name once procurement is confirmed.
// Fallbacks mirror the prototype's font stack so Century Gothic / Gill Sans renders
// on machines where Futura Round is unavailable — much closer to the brand look than Arial.
export const FONT_REGULAR =
  "'FONTSPRING DEMO - Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";
export const FONT_MEDIUM =
  "'FONTSPRING DEMO - Futura Round Medium', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";

export const FONT_SERIF = "'Source Serif 4', 'Georgia', serif";

export const fonts = {
  heading: FONT_MEDIUM,
  body: FONT_REGULAR,
  mono: FONT_REGULAR,
};

