// Load .env (at repo root) into process.env (no dotenv dependency needed).
// Variables already set in the shell environment take precedence.
const fs = require('fs');
const path = require('path');
try {
  const envLines = fs.readFileSync(path.join(process.cwd(), '.env'), 'utf8').split('\n');
  for (const line of envLines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;
    const key = trimmed.slice(0, eqIdx).trim();
    const value = trimmed.slice(eqIdx + 1).trim();
    if (key && !(key in process.env)) {
      process.env[key] = value;
    }
  }
} catch (_) {
  // .env is optional — no-op if absent
}

