import React from 'react';
import { Box, Image } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ContentfulLivePreview } from '@contentful/live-preview';
import type { ContentfulAsset, Hotspot } from '../../../types/contentful';
import HotspotMarker from './hotspotMarker';

type ShoppableImageProps = {
  image?: string | ContentfulAsset;
  imageAlt?: string;
  hotspots?: string;
  entryId?: string;
  locale?: string;
};

const parseHotspots = (raw: string | undefined): Hotspot[] => {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (h): h is Hotspot =>
        typeof h === 'object' &&
        h !== null &&
        typeof h.x === 'number' &&
        typeof h.y === 'number' &&
        typeof h.productId === 'string' &&
        h.productId.length > 0,
    );
  } catch {
    return [];
  }
};

const resolveImageUrl = (image: string | ContentfulAsset | undefined): string => {
  if (!image) return '';
  if (typeof image === 'string') return image;
  const url = image.fields.file.url;
  return url.startsWith('//') ? `https:${url}` : url;
};

const resolveImageAlt = (image: string | ContentfulAsset | undefined, fallback?: string): string => {
  if (!image || typeof image === 'string') return fallback ?? '';
  return image.fields.title ?? fallback ?? '';
};

const ShoppableImage = ({ image, imageAlt, hotspots, entryId, locale = 'en-US' }: ShoppableImageProps) => {
  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'image', locale }) : {};
  const parsedHotspots = parseHotspots(hotspots);
  const src = resolveImageUrl(image);
  const alt = imageAlt ?? resolveImageAlt(image);

  return (
    <Box position="relative" w="100%" {...inspectorProps}>
      <Image src={src} alt={alt} w="100%" display="block" loading="lazy" />
      {parsedHotspots.map((hotspot, i) => (
        <HotspotMarker key={i} x={hotspot.x} y={hotspot.y} productId={hotspot.productId} />
      ))}
    </Box>
  );
};

export default ShoppableImage;

