import React from 'react';
import { Box } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ContentfulLivePreview } from '@contentful/live-preview';
import type { ContentfulAsset } from '../../types/contentful';

type VideoEmbedProps = {
  videoEmbed: ContentfulAsset;
  entryId?: string;
  locale?: string;
};

export const VideoEmbed = ({ videoEmbed, entryId, locale = 'en-US' }: VideoEmbedProps) => {
  if (!videoEmbed?.fields?.file?.url) {
    console.error('VideoEmbed: Missing required data', videoEmbed);
    return null;
  }

  const { fields } = videoEmbed;
  const videoUrl = `https:${fields.file.url}`;
  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'videoEmbed', locale }) : {};

  return (
    <Box padding={8} maxWidth="container.xl" marginX="auto" {...inspectorProps}>
      <Box as="video" width="full" controls poster={fields.description}>
        <source src={videoUrl} type={fields.file.contentType} />
        Your browser does not support the video tag.
      </Box>
    </Box>
  );
};

