//   Tablet   (md,   768–1279px): 8 columns, 24px container padding, 1px gutter
//   Desktop  (xl,  ≥ 1280px):  10 columns,  0px container padding, 1px gutter

// prettier-ignore
export const breakpoints = {
  base: '0em',
  sm: '30em',       // NOT used (480px)
  md: '48em', // 768px — tablet breakpoint
  lg: '62em',       // NOT used (992px)
  xl: '80em', // 1280px — desktop breakpoint
  '2xl': '96em',    // NOT used (1536px)
} as const;

export const grid = {
  columns: { base: 4, md: 8, xl: 10 },
  containerPadding: { base: '30px', md: '24px', xl: '0' },
  columnGap: '1px',
} as const;

