import React from 'react';
import {
  Box,
  Popover,
  PopoverArrow,
  PopoverBody,
  PopoverContent,
  PopoverTrigger,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { keyframes } from '@chakra-ui/react';
import HotspotPopup from './hotspotPopup';

type HotspotMarkerProps = {
  x: number;
  y: number;
  productId: string;
};

const pulseRing = keyframes`
  0%   { transform: scale(1);   opacity: 0.6; }
  70%  { transform: scale(2);   opacity: 0; }
  100% { transform: scale(1);   opacity: 0; }
`;

const MARKER_SIZE = '16px';

const HotspotMarker = ({ x, y, productId }: HotspotMarkerProps) => (
  <Box position="absolute" left={`${x}%`} top={`${y}%`} transform="translate(-50%, -50%)" zIndex={1}>
    <Popover isLazy placement="top" trigger="hover">
      <PopoverTrigger>
        <Box position="relative" w={MARKER_SIZE} h={MARKER_SIZE} cursor="pointer">
          {/* Pulse ring */}
          <Box
            position="absolute"
            inset={0}
            borderRadius="full"
            bg="white"
            opacity={0.6}
            animation={`${pulseRing} 1.8s ease-out infinite`}
          />
          {/* Solid dot */}
          <Box position="absolute" inset={0} borderRadius="full" bg="white" boxShadow="0 0 0 2px rgba(0,0,0,0.25)" />
        </Box>
      </PopoverTrigger>
      <PopoverContent w="auto" border="none" boxShadow="lg" p={3}>
        <PopoverArrow />
        <PopoverBody p={0}>
          <HotspotPopup productId={productId} />
        </PopoverBody>
      </PopoverContent>
    </Popover>
  </Box>
);

export default HotspotMarker;

