import React from 'react';
import { Box, Button, Heading, Text } from '@salesforce/retail-react-app/app/components/shared/ui';

export type CollectionHeroProps = {
  headline?: string;
  subheadline?: string;
  ctaLabel?: string;
  ctaUrl?: string;
  backgroundImage?: string;
};

const CollectionHero = ({ headline, subheadline, ctaLabel, ctaUrl, backgroundImage }: CollectionHeroProps) => (
  <Box
    position="relative"
    minH="70vh"
    display="flex"
    alignItems="center"
    justifyContent="center"
    backgroundImage={backgroundImage ? `url(${backgroundImage})` : undefined}
    backgroundSize="cover"
    backgroundPosition="center"
  >
    <Box textAlign="center" color="white" px={8} py={16}>
      {headline && (
        <Heading as="h1" size="2xl" mb={4} textShadow="0 1px 4px rgba(0,0,0,0.4)">
          {headline}
        </Heading>
      )}
      {subheadline && (
        <Text fontSize="xl" mb={8} textShadow="0 1px 4px rgba(0,0,0,0.4)">
          {subheadline}
        </Text>
      )}
      {ctaLabel && ctaUrl && (
        <Button as="a" href={ctaUrl} size="lg" variant="outline" color="white" borderColor="white">
          {ctaLabel}
        </Button>
      )}
    </Box>
  </Box>
);

export default CollectionHero;

