// Minimal structural types for SSR Express handlers.
// @types/express is not installed as a direct dependency; these interfaces cover
// only the members each handler actually uses, and are structurally compatible
// with express.Request / express.Response so real express objects satisfy them at runtime.

export type SsrReq = {
  protocol: string;
  body: Record<string, string>;
  get(header: string): string | undefined;
  params: Record<string, string>;
  query: Record<string, string | string[]>;
  headers: Record<string, string | string[] | undefined>;
};

// `this` return type requires interface (not type alias) for polymorphic self-type
export interface SsrRes {
  send(body?: unknown): this;
  json(body: unknown): this;
  status(code: number): this;
  setHeader(name: string, value: string): this;
  set(field: string, value: string): this;
}

