import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { Button } from './index';

const meta: Meta<typeof Button> = {
  title: 'Elements/Button',
  component: Button,
  tags: ['autodocs'],
  parameters: {
    layout: 'centered',
  },
  argTypes: {
    variant: {
      control: 'radio',
      options: ['primary', 'secondary'],
    },
    size: {
      control: 'radio',
      options: ['lg', 'sm'],
    },
    price: {
      control: 'text',
    },
    isDisabled: {
      control: 'boolean',
    },
    isLoading: {
      control: 'boolean',
    },
    children: {
      control: 'text',
    },
  },
};

export default meta;

type Story = StoryObj<typeof Button>;

export const Default: Story = {
  args: {
    children: 'Button',
    variant: 'primary',
    size: 'lg',
  },
};

export const Secondary: Story = {
  args: {
    children: 'Button',
    variant: 'secondary',
    size: 'lg',
  },
};

export const WithPrice: Story = {
  name: 'With Price',
  args: {
    children: 'Add to Bag',
    variant: 'primary',
    size: 'lg',
    price: '$575',
  },
};

export const Small: Story = {
  args: {
    children: 'Button',
    variant: 'primary',
    size: 'sm',
  },
};

export const SmallSecondary: Story = {
  name: 'Small Secondary',
  args: {
    children: 'Button',
    variant: 'secondary',
    size: 'sm',
  },
};

export const Disabled: Story = {
  args: {
    children: 'Button',
    variant: 'primary',
    size: 'lg',
    isDisabled: true,
  },
};

export const DisabledSecondary: Story = {
  name: 'Disabled Secondary',
  args: {
    children: 'Button',
    variant: 'secondary',
    size: 'lg',
    isDisabled: true,
  },
};

export const Loading: Story = {
  args: {
    children: 'Adding…',
    variant: 'primary',
    size: 'lg',
    isLoading: true,
  },
};

